// Build lookup: key = "cardA|cardB|lane" -> MatchupEntry
// Note: cardA vs cardB is stored in one direction; reverse is computed.
const matchupMap = new Map<string, MatchupEntry>();

for (const [a, b, lane, winsA, total] of MATCHUP_DATA) {
  const key = `${a}|${b}|${lane}`;
  matchupMap.set(key, { cardA: a, cardB: b, lane, winsA, total });
}

export function getMatchup(cardA: string, cardB: string, lane: Lane): MatchupEntry | null {
  // Try both directions
  let entry = matchupMap.get(`${cardA}|${cardB}|${lane}`);
  if (entry) return entry;

  entry = matchupMap.get(`${cardB}|${cardA}|${lane}`);
  if (entry) {
    // Reverse: if B has winsA against A, then A has (total - winsA) against B
    return {
      cardA,
      cardB,
      lane,
      winsA: entry.total - entry.winsA,
      total: entry.total,
    };
  }

  return null; // no direct matchup data
}

export function getAllMatchups(): MatchupEntry[] {
  return Array.from(matchupMap.values());
}
